# The ten Bardic tales. Sound refs are "ALIAS:path suffix" (resolved against the repo lists).
# A sound is (card name, recipe[, options]).  Recipes:
#   "REF"                         one source
#   ("REF", "ffmpeg -af filter")  one source with a filter
#   ("mix", [(REF, delay_s, gain), ...], length_s|None)  layered sources
#   ("seq", [REF, ...], gap_s)    sources played one after another
# Options dict: loop ("once", "twice", "infinite", "random"), vol (0..1), trim (max seconds), start (s)

DOWN = lambda r: f"asetrate=44100*{r},aresample=44100"
ECHO_HALL = "aecho=0.8:0.6:120|260:0.35|0.22"
ECHO_CAVE = "aecho=0.8:0.7:180|420|700:0.4|0.28|0.15"
MUFFLE = "lowpass=f=900"

